function validate([time, totalTrips]) {
  if (!Array.isArray(time) || time.length < 1 || time.length > 100000) return 'time needs 1 to 10^5 values.';
  if (time.some(t => !Number.isInteger(t) || t < 1 || t > 10000000)) return 'Each trip time is a whole number from 1 to 10^7.';
  if (!Number.isInteger(totalTrips) || totalTrips < 1 || totalTrips > 10000000) return 'totalTrips is a whole number from 1 to 10^7.';
  return null;
}

