function minimumTime(time, totalTrips) {
  // Step from one finishing moment to the next until enough trips are done.
  const finished = (moment) => time.reduce((total, t) => total + Math.floor(moment / t), 0);
  // By any moment m at most m * sum(1 / t) trips are done, so this start is surely too early.
  const rate = time.reduce((total, t) => total + 1 / t, 0);
  let moment = Math.max(0, Math.floor(totalTrips / rate * (1 - 1e-9)) - 1);
  while (finished(moment) < totalTrips) {
    let next = Infinity;
    for (const t of time) next = Math.min(next, (Math.floor(moment / t) + 1) * t);
    moment = next;
  }
  return moment;
}

