function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const shape = rand();
    if (shape < 0.3) return [Array.from({ length: 2000 }, () => int(1, 10000000)), int(1, 10000000)];
    if (shape < 0.5) return [Array.from({ length: int(1, 3) }, () => int(9000000, 10000000)), int(9000000, 10000000)];
    if (shape < 0.7) {
      const same = int(1, 10000000);
      return [Array.from({ length: 2000 }, () => same), int(1, 10000000)];
    }
    return [Array.from({ length: 2000 }, () => int(1, 100)), int(1, 10000000)];
  }
  const n = int(1, 6);
  const top = rand() < 0.4 ? 3 : 12;
  return [Array.from({ length: n }, () => int(1, top)), int(1, 30)];
}
